/// A physical table. Conformances are generated by `@Table`.
public protocol Table: RowDecodable {
    /// The container of typed columns: `columns.groupID` is a `Column<Self, GroupID>`.
    associatedtype Columns: Sendable

    /// The schema the table lives in; the default for every query on it.
    ///
    /// A query can pick another attached copy with `all(in:)`, `join(_:in:)` or `find(_:in:)`.
    static var schema: DatabaseFile { get }
    static var tableName: String { get }

    /// The typed columns. Key paths into it (`\.groupID`) back `TableRef.groupID` and index declarations.
    static var columns: Columns { get }

    /// The column whose `NULL` marks a missing row in a `LEFT JOIN`. Defaults to the first column.
    static var identityColumn: Int32 { get }

    /// The table's schema metadata: columns, key and indexes.
    static var descriptor: TableDescriptor<Self> { get }
}

extension Table {
    @inlinable public static var schema: DatabaseFile { .main }

    /// The schema name, derived from `schema`.
    @inlinable public static var schemaName: String { schema.schemaName }
    @inlinable public static var identityColumn: Int32 { 0 }
    @inlinable public static var width: Int32 { Int32(descriptor.columns.count) }
}
